SELECT CAST('scheme_parameter' AS VARCHAR) AS kind, CAST('value' AS VARCHAR) AS slot, CAST(id AS VARCHAR) AS id, v FROM "scheme_parameter__value"
UNION ALL
SELECT CAST('status_lookup' AS VARCHAR) AS kind, CAST('looked_up_on_day' AS VARCHAR) AS slot, CAST(id AS VARCHAR) AS id, v FROM "status_lookup__looked_up_on_day"
UNION ALL
SELECT CAST('trust_entry' AS VARCHAR) AS kind, CAST('valid_from_day' AS VARCHAR) AS slot, CAST(id AS VARCHAR) AS id, v FROM "trust_entry__valid_from_day"
UNION ALL
SELECT CAST('trust_entry' AS VARCHAR) AS kind, CAST('valid_until_day' AS VARCHAR) AS slot, CAST(id AS VARCHAR) AS id, v FROM "trust_entry__valid_until_day";

CREATE LOCAL VIEW "rede__enum_value" AS
SELECT CAST('bound_side' AS VARCHAR) AS enumeration, id FROM "bound_side"
UNION ALL
SELECT CAST('capability' AS VARCHAR) AS enumeration, id FROM "capability"
UNION ALL
SELECT CAST('decision_state' AS VARCHAR) AS enumeration, id FROM "decision_state"
UNION ALL
SELECT CAST('eligibility' AS VARCHAR) AS enumeration, id FROM "eligibility"
UNION ALL
SELECT CAST('interval_relation' AS VARCHAR) AS enumeration, id FROM "interval_relation"
UNION ALL
SELECT CAST('judgement_reason' AS VARCHAR) AS enumeration, id FROM "judgement_reason"
UNION ALL
SELECT CAST('judgement_value' AS VARCHAR) AS enumeration, id FROM "judgement_value"
UNION ALL
SELECT CAST('parameter_unit' AS VARCHAR) AS enumeration, id FROM "parameter_unit"
UNION ALL
SELECT CAST('status_value' AS VARCHAR) AS enumeration, id FROM "status_value";

CREATE MATERIALIZED VIEW "rede__identification" AS
SELECT kind, CAST('' AS VARCHAR) AS slot, CAST('' AS VARCHAR) AS path, id, CAST(COUNT(*) AS VARCHAR) AS value FROM "rede__element" GROUP BY kind, id HAVING COUNT(*) > 1;

CREATE MATERIALIZED VIEW "rede__reference" AS
SELECT * FROM (
SELECT m.kind AS kind, CAST('is_a' AS VARCHAR) AS slot, CAST('is_a' AS VARCHAR) AS path, e.id AS id, CAST('' AS VARCHAR) AS value FROM "rede__is_a" m JOIN "rede__element" e ON e.kind = m.kind
EXCEPT SELECT m.kind, CAST('is_a' AS VARCHAR), CAST('is_a' AS VARCHAR), p.id, CAST('' AS VARCHAR) FROM "rede__is_a" m JOIN "rede__element" p ON p.kind = m.parent
) r1
UNION
SELECT * FROM (
SELECT x.kind AS kind, x.slot AS slot, x.slot AS path, x.id AS id, x.v AS value FROM "rede__value" x
EXCEPT SELECT x.kind, x.slot, x.slot, x.id, x.v FROM "rede__value" x JOIN "rede__element" e ON e.kind = x.kind AND e.id = x.id
) r2
UNION
SELECT * FROM (
SELECT x.kind AS kind, x.slot AS slot, x.slot AS path, x.id AS id, x.v AS value FROM "rede__value" x JOIN "rede__arrow" m ON m.kind = x.kind AND m.slot = x.slot
EXCEPT SELECT x.kind, x.slot, x.slot, x.id, x.v FROM "rede__value" x JOIN "rede__arrow" m ON m.kind = x.kind AND m.slot = x.slot JOIN "rede__element" t ON t.kind = m.target AND t.id = x.v
) r3;

CREATE MATERIALIZED VIEW "rede__totality" AS
SELECT m.kind AS kind, m.slot AS slot, m.slot AS path, e.id AS id, CAST('' AS VARCHAR) AS value FROM "rede__required" m JOIN "rede__element" e ON e.kind = m.kind
EXCEPT SELECT kind, slot, slot, id, CAST('' AS VARCHAR) FROM "rede__value";

CREATE MATERIALIZED VIEW "rede__functionality" AS
SELECT x.kind AS kind, x.slot AS slot, x.slot AS path, x.id AS id, CAST(COUNT(DISTINCT x.v) AS VARCHAR) AS value FROM "rede__value" x JOIN "rede__single" m ON m.kind = x.kind AND m.slot = x.slot
GROUP BY x.kind, x.slot, x.id HAVING COUNT(DISTINCT x.v) > 1;

CREATE MATERIALIZED VIEW "rede__value_range" AS
SELECT DISTINCT kind, slot, slot AS path, id, v AS value FROM (
SELECT * FROM (
SELECT x.kind, x.slot, x.id, x.v FROM "rede__value" x JOIN "rede__enum" m ON m.kind = x.kind AND m.slot = x.slot
EXCEPT SELECT x.kind, x.slot, x.id, x.v FROM "rede__value" x JOIN "rede__enum" m ON m.kind = x.kind AND m.slot = x.slot JOIN "rede__enum_value" a ON a.enumeration = m.enumeration AND a.id = x.v
) r1
UNION ALL
SELECT * FROM (
SELECT i.kind, i.slot, i.id, CAST(i.v AS VARCHAR) AS v FROM "rede__integer" i JOIN "rede__minimum" b ON b.kind = i.kind AND b.slot = i.slot WHERE i.v < b.v
) r2
UNION ALL
SELECT * FROM (
SELECT i.kind, i.slot, i.id, CAST(i.v AS VARCHAR) AS v FROM "rede__integer" i JOIN "rede__maximum" b ON b.kind = i.kind AND b.slot = i.slot WHERE i.v > b.v
) r3
UNION ALL
SELECT * FROM (
SELECT x.kind, x.slot, x.id, x.v FROM "rede__value" x JOIN (SELECT DISTINCT kind, slot FROM "rede__constant") m ON m.kind = x.kind AND m.slot = x.slot
EXCEPT SELECT x.kind, x.slot, x.id, x.v FROM "rede__value" x JOIN (SELECT DISTINCT kind, slot FROM "rede__constant") m ON m.kind = x.kind AND m.slot = x.slot JOIN "rede__constant" c ON c.kind = x.kind AND c.slot = x.slot AND c.v = x.v
) r4
) y;

CREATE MATERIALIZED VIEW "rede__cardinality" AS
SELECT c.kind AS kind, c.slot AS slot, c.slot AS path, c.id AS id, CAST(c.n AS VARCHAR) AS value FROM (SELECT x.kind AS kind, x.slot AS slot, x.id AS id, COUNT(DISTINCT x.v) AS n FROM "rede__value" x JOIN (SELECT kind, slot FROM "rede__minimum_cardinality" UNION SELECT kind, slot FROM "rede__maximum_cardinality") l ON l.kind = x.kind AND l.slot = x.slot JOIN "rede__element" e ON e.kind = x.kind AND e.id = x.id GROUP BY x.kind, x.slot, x.id
UNION ALL SELECT kind, slot, id, CAST(0 AS BIGINT) AS n FROM (
SELECT l.kind AS kind, l.slot AS slot, e.id AS id FROM (SELECT kind, slot FROM "rede__minimum_cardinality" UNION SELECT kind, slot FROM "rede__maximum_cardinality") l JOIN "rede__element" e ON e.kind = l.kind
EXCEPT SELECT kind, slot, id FROM "rede__value") z) c JOIN "rede__minimum_cardinality" b ON b.kind = c.kind AND b.slot = c.slot WHERE c.n < b.v
UNION
SELECT c.kind AS kind, c.slot AS slot, c.slot AS path, c.id AS id, CAST(c.n AS VARCHAR) AS value FROM (SELECT x.kind AS kind, x.slot AS slot, x.id AS id, COUNT(DISTINCT x.v) AS n FROM "rede__value" x JOIN (SELECT kind, slot FROM "rede__minimum_cardinality" UNION SELECT kind, slot FROM "rede__maximum_cardinality") l ON l.kind = x.kind AND l.slot = x.slot JOIN "rede__element" e ON e.kind = x.kind AND e.id = x.id GROUP BY x.kind, x.slot, x.id
UNION ALL SELECT kind, slot, id, CAST(0 AS BIGINT) AS n FROM (
SELECT l.kind AS kind, l.slot AS slot, e.id AS id FROM (SELECT kind, slot FROM "rede__minimum_cardinality" UNION SELECT kind, slot FROM "rede__maximum_cardinality") l JOIN "rede__element" e ON e.kind = l.kind
EXCEPT SELECT kind, slot, id FROM "rede__value") z) c JOIN "rede__maximum_cardinality" b ON b.kind = c.kind AND b.slot = c.slot WHERE c.n > b.v;

CREATE MATERIALIZED VIEW "rede__pattern" AS
SELECT CAST('credential' AS VARCHAR) AS kind, CAST('issuer' AS VARCHAR) AS slot, CAST('issuer' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "credential__issuer" WHERE NOT RLIKE(v, '^https://[a-z0-9-]+\x2Einvented\x2Eexample$')
) x
UNION ALL
SELECT CAST('credential' AS VARCHAR) AS kind, CAST('subject' AS VARCHAR) AS slot, CAST('subject' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "credential__subject" WHERE NOT RLIKE(v, '^p-[a-z0-9]{8}$')
) x
UNION ALL
SELECT CAST('credential_claim' AS VARCHAR) AS kind, CAST('attribute' AS VARCHAR) AS slot, CAST('attribute' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "credential_claim__attribute" WHERE NOT RLIKE(v, '^[a-z][a-z0-9_]*$')
) x
UNION ALL
SELECT CAST('credential_claim' AS VARCHAR) AS kind, CAST('value' AS VARCHAR) AS slot, CAST('value' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "credential_claim__value" WHERE NOT RLIKE(v, '^[a-z][a-z0-9_]*$')
) x
UNION ALL
SELECT CAST('identity_statement' AS VARCHAR) AS kind, CAST('first_identifier' AS VARCHAR) AS slot, CAST('first_identifier' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "identity_statement__first_identifier" WHERE NOT RLIKE(v, '^p-[a-z0-9]{8}$')
) x
UNION ALL
SELECT CAST('identity_statement' AS VARCHAR) AS kind, CAST('first_node' AS VARCHAR) AS slot, CAST('first_node' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "identity_statement__first_node" WHERE NOT RLIKE(v, '^https://[a-z0-9-]+\x2Einvented\x2Eexample$')
) x
UNION ALL
SELECT CAST('identity_statement' AS VARCHAR) AS kind, CAST('issuer' AS VARCHAR) AS slot, CAST('issuer' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "identity_statement__issuer" WHERE NOT RLIKE(v, '^https://[a-z0-9-]+\x2Einvented\x2Eexample$')
) x
UNION ALL
SELECT CAST('identity_statement' AS VARCHAR) AS kind, CAST('second_identifier' AS VARCHAR) AS slot, CAST('second_identifier' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "identity_statement__second_identifier" WHERE NOT RLIKE(v, '^p-[a-z0-9]{8}$')
) x
UNION ALL
SELECT CAST('identity_statement' AS VARCHAR) AS kind, CAST('second_node' AS VARCHAR) AS slot, CAST('second_node' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "identity_statement__second_node" WHERE NOT RLIKE(v, '^https://[a-z0-9-]+\x2Einvented\x2Eexample$')
) x
UNION ALL
SELECT CAST('scheme_parameter' AS VARCHAR) AS kind, CAST('name' AS VARCHAR) AS slot, CAST('name' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "scheme_parameter__name" WHERE NOT RLIKE(v, '^[a-z][a-z0-9_]*$')
) x
UNION ALL
SELECT CAST('trust_entry' AS VARCHAR) AS kind, CAST('attribute' AS VARCHAR) AS slot, CAST('attribute' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "trust_entry__attribute" WHERE NOT RLIKE(v, '^[a-z][a-z0-9_]*$')
) x
UNION ALL
SELECT CAST('trust_entry' AS VARCHAR) AS kind, CAST('issuer' AS VARCHAR) AS slot, CAST('issuer' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "trust_entry__issuer" WHERE NOT RLIKE(v, '^https://[a-z0-9-]+\x2Einvented\x2Eexample$')
) x
UNION ALL
SELECT CAST('trust_entry' AS VARCHAR) AS kind, CAST('node' AS VARCHAR) AS slot, CAST('node' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST(v AS VARCHAR) AS value FROM (
SELECT DISTINCT id, v FROM "trust_entry__node" WHERE NOT RLIKE(v, '^https://[a-z0-9-]+\x2Einvented\x2Eexample$')
) x;

CREATE MATERIALIZED VIEW "rede__unique" AS
SELECT CAST('ground' AS VARCHAR) AS kind, CAST('ground_pair' AS VARCHAR) AS slot, CAST('decision,rests_on' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST('' AS VARCHAR) AS value FROM (
WITH t AS (SELECT e.id AS id, c0.v AS c0, c1.v AS c1 FROM "ground" e JOIN "ground__decision" c0 ON c0.id = e.id JOIN "ground__rests_on" c1 ON c1.id = e.id)
SELECT DISTINCT a.id AS id FROM t a JOIN t b ON a.c0 = b.c0 AND a.c1 = b.c1 AND a.id <> b.id
) x;

CREATE MATERIALIZED VIEW "rede__rule" AS
SELECT CAST('decision' AS VARCHAR) AS kind, CAST('rule_1' AS VARCHAR) AS slot, CAST('valid_from => valid_from_day' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST('' AS VARCHAR) AS value FROM (
SELECT DISTINCT e.id AS id FROM "decision" e WHERE ((e.id IN (SELECT id FROM "decision__valid_from"))) AND NOT ((e.id IN (SELECT id FROM "decision__valid_from_day")))
) x
UNION ALL
SELECT CAST('decision' AS VARCHAR) AS kind, CAST('rule_2' AS VARCHAR) AS slot, CAST('valid_from_day => valid_from' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST('' AS VARCHAR) AS value FROM (
SELECT DISTINCT e.id AS id FROM "decision" e WHERE ((e.id IN (SELECT id FROM "decision__valid_from_day"))) AND NOT ((e.id IN (SELECT id FROM "decision__valid_from")))
) x
UNION ALL
SELECT CAST('decision' AS VARCHAR) AS kind, CAST('rule_3' AS VARCHAR) AS slot, CAST('valid_until => valid_until_day' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST('' AS VARCHAR) AS value FROM (
SELECT DISTINCT e.id AS id FROM "decision" e WHERE ((e.id IN (SELECT id FROM "decision__valid_until"))) AND NOT ((e.id IN (SELECT id FROM "decision__valid_until_day")))
) x
UNION ALL
SELECT CAST('decision' AS VARCHAR) AS kind, CAST('rule_4' AS VARCHAR) AS slot, CAST('valid_until_day => valid_until' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST('' AS VARCHAR) AS value FROM (
SELECT DISTINCT e.id AS id FROM "decision" e WHERE ((e.id IN (SELECT id FROM "decision__valid_until_day"))) AND NOT ((e.id IN (SELECT id FROM "decision__valid_until")))
) x
UNION ALL
SELECT CAST('decision' AS VARCHAR) AS kind, CAST('rule_5' AS VARCHAR) AS slot, CAST('state, valid_from => valid_until' AS VARCHAR) AS path, CAST(id AS VARCHAR) AS id, CAST('' AS VARCHAR) AS value FROM (
SELECT DISTINCT e.id AS id FROM "decision" e WHERE ((e.id IN (SELECT id FROM "decision__state") AND e.id NOT IN (SELECT id FROM "decision__state" WHERE NOT (v = 'withdrawn'))) AND (e.id IN (SELECT id FROM "decision__valid_from"))) AND NOT ((e.id IN (SELECT id FROM "decision__valid_until")))
) x;

CREATE MATERIALIZED VIEW "validation_result" AS
SELECT CAST('identification' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__identification' ELSE kind || '__' || slot || '__identification' END AS info FROM "rede__identification"
UNION ALL
SELECT CAST('reference' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__reference' ELSE kind || '__' || slot || '__reference' END AS info FROM "rede__reference"
UNION ALL
SELECT CAST('totality' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__totality' ELSE kind || '__' || slot || '__totality' END AS info FROM "rede__totality"
UNION ALL
SELECT CAST('functionality' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__functionality' ELSE kind || '__' || slot || '__functionality' END AS info FROM "rede__functionality"
UNION ALL
SELECT CAST('value_range' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__value_range' ELSE kind || '__' || slot || '__value_range' END AS info FROM "rede__value_range"
UNION ALL
SELECT CAST('cardinality' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__cardinality' ELSE kind || '__' || slot || '__cardinality' END AS info FROM "rede__cardinality"
UNION ALL
SELECT CAST('pattern' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__pattern' ELSE kind || '__' || slot || '__pattern' END AS info FROM "rede__pattern"
UNION ALL
SELECT CAST('unique' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__unique' ELSE kind || '__' || slot || '__unique' END AS info FROM "rede__unique"
UNION ALL
SELECT CAST('rule' AS VARCHAR) AS type, id AS subject, kind AS instantiates, path, value, CASE WHEN slot = '' THEN kind || '__rule' ELSE kind || '__' || slot || '__rule' END AS info FROM "rede__rule";

-- Seal (decision E3): refused and accepted input of the sealed kind; rules read the accepted rows.
CREATE MATERIALIZED VIEW "ledger_payment__refused" AS
SELECT DISTINCT a.id AS id, a.period_close AS period_close
FROM (
  SELECT p.id AS id, u.id AS period_close FROM "ledger_payment__booked_on" AS p
    CROSS JOIN "period_close__closed_until" AS u WHERE p.v < u.v
  UNION
  SELECT k.id AS id, v.id AS period_close FROM "ledger_payment" AS k
    JOIN "closed_payment__element" AS e ON e.v = k.id
    JOIN "period_close__covers" AS v ON v.v = e.id
) AS a
LEFT JOIN (
  SELECT e.v AS id, v.id AS period_close FROM "closed_payment__element" AS e
    JOIN "closed_payment__sha256" AS c ON c.id = e.id
    JOIN "ledger_payment__row_sha256" AS h ON h.id = e.v AND h.v = c.v
    JOIN "period_close__covers" AS v ON v.v = e.id
) AS m ON m.id = a.id AND m.period_close = a.period_close
WHERE m.id IS NULL;

CREATE MATERIALIZED VIEW "ledger_payment__accepted" AS
SELECT DISTINCT e.id AS id FROM "ledger_payment" AS e
LEFT JOIN "ledger_payment__refused" AS r ON r.id = e.id WHERE r.id IS NULL;

